-- Real invoice data sourced from invoice_and_do/*.xlsx files.
-- Runs after 05_real_purchase_orders.sql.
--
-- Strategy:
--   1. Ensure each real PO has an invoice row (call fn_create_invoice for
--      POs whose status never reached DELIVERED in seed 04).
--   2. Override invoice_date / due_date / status with values pulled from the
--      .xlsx files.
--   3. Invoice numbers, line items, dpp, ppn stay as the auto-generated values
--      because items mirror purchase_order_items (snapshot rebuilt by 05).
--
-- Status heuristic: invoice with due_date <= 2026-05-09 -> 'paid', else 'sent'.
-- Coverage: 54/55 POs matched to invoice files. qid 549 (Q-2640061) has a real
-- PO but no invoice file yet, so it stays accepted with a PO and no invoice.

BEGIN;

-- 1. Create invoice rows for real-PO quotations that didn't auto-gen one.
DO $$
DECLARE r RECORD;
BEGIN
  FOR r IN
    SELECT po.id, COALESCE(po.updated_by, po.created_by) AS user_id
      FROM purchase_orders po
      JOIN (VALUES
        (478::bigint),
        (481::bigint),
        (486::bigint),
        (488::bigint),
        (489::bigint),
        (490::bigint),
        -- Q-491 dropped: unpriced quotation, stays draft (see 04).
        (492::bigint),
        (498::bigint),
        (500::bigint),
        (506::bigint),
        (509::bigint),
        (512::bigint),
        (519::bigint),
        (520::bigint),
        (522::bigint),
        (523::bigint),
        (524::bigint),
        (526::bigint),
        (528::bigint),
        (530::bigint),
        (537::bigint),
        (542::bigint),
        (543::bigint),
        (544::bigint),
        (548::bigint),
        (552::bigint),
        (555::bigint),
        (556::bigint),
        (557::bigint),
        (565::bigint),
        (568::bigint),
        (571::bigint),
        (573::bigint),
        (575::bigint),
        (576::bigint),
        (587::bigint),
        (589::bigint),
        (593::bigint),
        (604::bigint),
        (605::bigint),
        (611::bigint),
        (614::bigint),
        (619::bigint),
        -- Q-624 dropped: unpriced quotation, stays draft (see 04).
        (640::bigint),
        (641::bigint),
        (643::bigint),
        (645::bigint),
        (646::bigint),
        (647::bigint),
        (649::bigint),
        (654::bigint),
        (660::bigint),
        (668::bigint),
        (669::bigint)
      ) AS rp(quotation_id) ON rp.quotation_id = po.quotation_id
      WHERE NOT EXISTS (SELECT 1 FROM invoices i WHERE i.po_id = po.id)
  LOOP
    PERFORM fn_create_invoice(r.id, r.user_id);
  END LOOP;
END $$;

-- 2. Override invoice header (date / due / status). Invoice number stays as
--    auto-generated by fn_next_doc_no, items are mirrored from PO.
UPDATE invoices i
   SET invoice_date = v.invoice_date,
       due_date     = v.due_date,
       status       = v.status,
       updated_by   = i.created_by
  FROM (VALUES
    (544::bigint, '2026-02-10'::date, '2026-03-12'::date, 'paid'),  -- 025_2_2026 - Siemens UVR - Karunia Aman Sentosa.xl
    (526::bigint, '2026-01-26'::date, '2026-02-25'::date, 'paid'),  -- 017_I_2026 - Karunia Aman Sentosa.xlsx
    (556::bigint, '2026-03-11'::date, '2026-04-10'::date, 'paid'),  -- 032_2_2026 - Selenoid Valve - Karunia Aman Sentosa
    (605::bigint, '2026-03-17'::date, '2026-04-16'::date, 'paid'),  -- 042_3_2026 - Power Supply Diamond GZV4000 - Karuni
    (557::bigint, '2026-02-25'::date, '2026-03-27'::date, 'paid'),  -- 033_2_2026 - Module Sices GC250 - Karunia Aman Sen
    (593::bigint, '2026-03-04'::date, '2026-04-03'::date, 'paid'),  -- 037_3_2026 - Nozzle Cleaner Gun - Karunia Aman Sen
    (646::bigint, '2026-05-07'::date, '2026-06-06'::date, 'sent'),  -- 056_5_2026 - Vbelt TB Aman 06 - Karunia Aman Sento
    (668::bigint, '2026-01-26'::date, '2026-02-25'::date, 'paid'),  -- 016_I_2026 - Karunia Aman Sentosa.xlsx
    (669::bigint, '2026-02-10'::date, '2026-03-12'::date, 'paid'),  -- 025_2_2026 - ComAp Inteli Nano Module - Karunia Am
