    (614::bigint, '2026-04-10'::date, '2026-05-10'::date, 'sent'),  -- 043_4_2026 - Racor 2040 2010 - Karunia Aman Selalu
    (640::bigint, '2026-04-20'::date, '2026-05-20'::date, 'sent'),  -- 051_4_2026 - Magnafluk - Karunia Aman Selalu.xlsx
    (654::bigint, '2026-05-02'::date, '2026-06-01'::date, 'sent'),  -- 054_5_2026 - Vbelt AE 3911588 - Karunia Aman Selal
