    (575::bigint, '2026-02-24'::date, '2026-03-26'::date, 'paid'),  -- 029_2_2026 - Freon 407 - Pelita Almeira Pertiwi -
    (528::bigint, '2026-02-03'::date, '2026-03-05'::date, 'paid'),  -- 018_1_2026 - ANGLE VALVE 10K 125 SDNR - Pelita Alm
