    -- Q-491 dropped: unpriced quotation, stays draft (see 04).
    (519::bigint, '2026-01-21'::date, '2026-02-20'::date, 'paid'),  -- 011_1_2026 - Impeller - Daidan Pertiwi - Pelita Gl
    (524::bigint, '2026-01-27'::date, '2026-02-26'::date, 'paid'),  -- 013_1_2026 - Angle Valve - Daidan Pertiwi - Pelita
    (522::bigint, '2026-01-27'::date, '2026-02-26'::date, 'paid'),  -- 012_1_2026 - Butterfly Valve double flange 5K 200
    (500::bigint, '2026-01-19'::date, '2026-02-18'::date, 'paid'),  -- 004_1_2026 - Cordless Impact Wrench - Daidan Perti
    (506::bigint, '2026-01-19'::date, '2026-02-18'::date, 'paid'),  -- 008_1_2026 - kunci shock, dakron dll  - Daidan Per
    (498::bigint, '2026-01-19'::date, '2026-02-18'::date, 'paid'),  -- 003_1_2026 - Wearpacks - Daidan Pertiwi - Pelita G
    (542::bigint, '2026-02-05'::date, '2026-03-07'::date, 'paid'),  -- 020_2_2026 - Pressure Gauge dll - Pelita Almeira P
    (520::bigint, '2026-01-19'::date, '2026-02-18'::date, 'paid')  -- 010_1_2026 - Marine Cast Iron F-7363 - Daidan Pert
  ) AS v(quotation_id, invoice_date, due_date, status)
  JOIN purchase_orders po ON po.quotation_id = v.quotation_id
 WHERE i.po_id = po.id;

-- 3. Sanity check: every real-PO invoice must have items matching its PO.
--    invoice_items mirrors purchase_order_items via fn_create_invoice +
--    migration 00021. This raises if any mismatch is detected.
DO $$
DECLARE n_mismatch INT;
BEGIN
  SELECT count(*) INTO n_mismatch FROM (
    SELECT po.id AS po_id,
           (SELECT count(*) FROM purchase_order_items WHERE po_id = po.id) AS po_n,
           (SELECT count(*) FROM invoice_items ii JOIN invoices i ON i.id=ii.invoice_id WHERE i.po_id = po.id) AS inv_n
      FROM purchase_orders po
      JOIN (VALUES
        (478::bigint),
        (481::bigint),
        (486::bigint),
        (488::bigint),
        (489::bigint),
        (490::bigint),
        -- Q-491 dropped: unpriced quotation, stays draft (see 04).
        (492::bigint),
        (498::bigint),
        (500::bigint),
        (506::bigint),
        (509::bigint),
        (512::bigint),
        (519::bigint),
        (520::bigint),
        (522::bigint),
        (523::bigint),
        (524::bigint),
        (526::bigint),
        (528::bigint),
        (530::bigint),
        (537::bigint),
        (542::bigint),
        (543::bigint),
        (544::bigint),
        (548::bigint),
        (552::bigint),
        (555::bigint),
        (556::bigint),
        (557::bigint),
        (565::bigint),
        (568::bigint),
        (571::bigint),
        (573::bigint),
        (575::bigint),
        (576::bigint),
        (587::bigint),
        (589::bigint),
        (593::bigint),
        (604::bigint),
        (605::bigint),
        (611::bigint),
        (614::bigint),
        (619::bigint),
        -- Q-624 dropped: unpriced quotation, stays draft (see 04).
        (640::bigint),
        (641::bigint),
        (643::bigint),
        (645::bigint),
        (646::bigint),
        (647::bigint),
        (649::bigint),
        (654::bigint),
        (660::bigint),
        (668::bigint),
        (669::bigint)
      ) AS rp(quotation_id) ON rp.quotation_id = po.quotation_id
  ) t WHERE po_n <> inv_n;
  IF n_mismatch > 0 THEN
    RAISE EXCEPTION 'Invoice item count mismatch on % real-PO invoices', n_mismatch;
  END IF;
END $$;

-- 4. An invoice existing means the goods were delivered. Advance every PO
--    that has an invoice to DELIVERED and stamp its delivery note number,
--    matching fn_change_po_status. Direct UPDATE is the seed-time exception:
--    fn_change_po_status would re-run the invoice draft.
UPDATE purchase_orders po
   SET status               = 'DELIVERED',
       delivery_note_number = COALESCE(
         po.delivery_note_number,
         fn_next_doc_no('DN')
       )
 WHERE po.status <> 'DELIVERED'
   AND EXISTS (SELECT 1 FROM invoices i WHERE i.po_id = po.id);

-- 5. Each invoice keeps the number it was issued under, from its file name
--    (011_1_2026 -> 011/1/2026), so the list search still finds it. The
--    original DO numbers are not on file, so legacy_dn_no stays NULL.
UPDATE invoices i
   SET legacy_no = v.legacy_no
  FROM (VALUES
    (478::bigint, '015/I/2026'),
    (481::bigint, '036/2/2026'),
